type ProductCardProps = { name: string; price: number; stock: number };

export function ProductCard({ name, price, stock }: ProductCardProps) {
  const label = stock === 0 ? "Sold out" : `${stock} left`;
  return (
    <article className="card">
      <h2>{name}</h2>
      <p>{price.toFixed(2)} USD</p>
      <p>{label}</p>
    </article>
  );
}

